"""用產品位圖呈現器逐格輸出六門近鏡；30fps是影片編碼，不宣稱裝置效能。"""
from pathlib import Path
from playwright.sync_api import sync_playwright
import base64,os
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/os.getenv('MARTIAL_QA_OUT','production/qa/evidence/redesign/independent-animations');TMP=Path('/tmp/full-martial-animations/gallery');TMP.mkdir(parents=True,exist_ok=True);BASE=os.getenv('MARTIAL_BASE','http://127.0.0.1:5292/')
with sync_playwright()as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.add_init_script("const ids=new Set(),raf=requestAnimationFrame.bind(window);window.requestAnimationFrame=f=>{const id=raf(t=>{ids.delete(id);f(t)});ids.add(id);return id};window.stopQa=()=>{for(const id of ids)cancelAnimationFrame(id);window.requestAnimationFrame=()=>0}");p.goto(BASE+'?martial-preview=1&art=art_river_fist&pose=1&clean=1');p.wait_for_function('!!window.__martialQa',timeout=90000);p.evaluate('stopQa()')
 p.evaluate('''async()=>{const{loadAppearanceAssets}=await import('/src/appearance/assets.ts'),{drawIndependentAppearance}=await import('/src/appearance/independent/draw.ts'),{INDEPENDENT_INDEX}=await import('/src/appearance/independent/frames.ts');const assets=await loadAppearanceAssets(),ids=['art_river_fist','art_stone_palm','art_thunder_blade','art_spear_cloud','art_bow_star','art_whip_silk'],outfits=['traveller','scholar','cloak'];const values=ids.map((id,i)=>({head:'bamboo',outfit:outfits[i%3],tone:['ink','jade','sand'][i%3]}));for(let i=0;i<ids.length;i++){const id=ids[i],v=values[i];await Promise.all([assets.independent.prepareClip(v,id),assets.independent.prepareUpper(v),assets.independent.prepareProp(INDEPENDENT_INDEX.clips[id].family)]);}await Promise.all(['cord','arrow'].map(k=>assets.independent.prepareProp(k)));const canvas=document.createElement('canvas');canvas.width=720;canvas.height=1050;const ctx=canvas.getContext('2d');window.galleryFrame=time=>{ctx.fillStyle='#eee6d6';ctx.fillRect(0,0,720,1050);ctx.fillStyle='#27221b';ctx.font='26px serif';ctx.fillText('獨立武學動作 · 保留所選造型',20,36);ctx.font='16px serif';ctx.fillText('產品呈現器逐幀輸出 · 非裝置幀率測試',20,61);for(let i=0;i<ids.length;i++){const id=ids[i],d=INDEPENDENT_INDEX.clips[id],x=85+(i%2)*360,y=365+Math.floor(i/2)*330,t=time%(d.duration+.45);ctx.font='22px serif';ctx.fillStyle='#27221b';ctx.fillText(d.name,20+(i%2)*360,y-265);if(!drawIndependentAppearance(ctx,assets,values[i],{x,y,height:230,martialId:id,motionTime:Math.min(t,d.duration),family:d.family,pose:'attack'}))throw Error('動作未備妥 '+id)}return canvas.toDataURL()};}''')
 for i in range(240):
  uri=p.evaluate('galleryFrame',i/30);(TMP/f'{i:04d}.png').write_bytes(base64.b64decode(uri.split(',')[1]))
 b.close();print('GALLERY_FRAMES',240)
